#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Phase 0 GCP bootstrap (SPEC §12.2, §13, §19): dev + prod projects, billing
# link, and budget alerts. Safe to re-run: each stage skips work already done.
# Run from anywhere:  ./infra/bootstrap/gcp-bootstrap.sh

TOTAL_STAGES=8

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
ENV_FILE="$REPO_ROOT/.env"

if ! command -v gcloud >/dev/null 2>&1; then
  printf '%sgcloud is not installed. Install the Google Cloud SDK first:%s\n' "$RED" "$RESET"
  printf '  https://cloud.google.com/sdk/docs/install\n'
  exit 1
fi

# _project_exists ID: true if the signed-in account can see the project.
_project_exists() { gcloud projects describe "$1" --format='value(projectId)' >/dev/null 2>&1; }

# _suggest PREFIX: a project ID suggestion with a random suffix (IDs are global).
_suggest() { printf '%s-%04x%02x' "$1" "$RANDOM" "$((RANDOM % 256))"; }

_valid_project_id() { [[ "$1" =~ ^[a-z][a-z0-9-]{4,28}[a-z0-9]$ ]]; }

banner "GCP bootstrap · Document Intelligence Pipeline"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Sign in to gcloud"
ACTIVE_ACCOUNT=$(gcloud auth list --filter=status:ACTIVE --format='value(account)' 2>/dev/null || true)
if [[ -n "$ACTIVE_ACCOUNT" ]]; then
  say "gcloud is signed in as ${BOLD}${ACTIVE_ACCOUNT}${RESET}."
  if ! confirm "Use this Google account for the projects and billing?"; then
    say "A browser window will open so you can sign in with the right account."
    gcloud auth login
  fi
else
  say "gcloud isn't signed in yet. A browser window will open so you can sign in."
  gcloud auth login
fi
ACTIVE_ACCOUNT=$(gcloud auth list --filter=status:ACTIVE --format='value(account)')
say "Using ${BOLD}${ACTIVE_ACCOUNT}${RESET}."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Pick the billing account"
say "Projects need a billing account before they can run anything."
say "Budgets are created on the billing account, so you need to be its"
say "Billing Account Administrator (true if you created it yourself)."
open_url "https://console.cloud.google.com/billing"
step "If you have no billing account yet, click 'Create account' and finish the form."
step "Note the Billing account ID: it looks like 01ABCD-23EF45-6789GH."
say ""
say "Billing accounts visible to ${ACTIVE_ACCOUNT}:"
gcloud billing accounts list --format='table(name.basename():label=ID, displayName:label=NAME, open:label=OPEN)' 2>/dev/null \
  | sed 's/^/    /' || warn "couldn't list billing accounts; copy the ID from the console instead"
say ""
while true; do
  ask DIP_GCP_BILLING_ACCOUNT "Paste the billing account ID:"
  [[ "$DIP_GCP_BILLING_ACCOUNT" =~ ^[0-9A-F]{6}-[0-9A-F]{6}-[0-9A-F]{6}$ ]] && break
  warn "That doesn't look like XXXXXX-XXXXXX-XXXXXX (uppercase hex). Try again."
done
write_env DIP_GCP_BILLING_ACCOUNT "$DIP_GCP_BILLING_ACCOUNT"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Choose project IDs"
say "Project IDs are global across all of Google Cloud and can never be reused,"
say "even after deletion. 6-30 chars: lowercase letters, digits, hyphens."
say "SPEC §13: dev and prod are separate projects for IAM and billing isolation."
say ""
for env_name in DEV PROD; do
  key="DIP_GCP_PROJECT_${env_name}"
  lower=$(printf '%s' "$env_name" | tr '[:upper:]' '[:lower:]')
  suggestion=$(_existing "$key" || _suggest "dip-${lower}")
  while true; do
    ask "$key" "${env_name} project ID [${suggestion}]:"
    [[ -z "${!key}" ]] && printf -v "$key" '%s' "$suggestion"
    _valid_project_id "${!key}" && break
    warn "Invalid project ID. Use 6-30 chars, start with a letter, no trailing hyphen."
  done
  write_env "$key" "${!key}"
done
if [[ "$DIP_GCP_PROJECT_DEV" == "$DIP_GCP_PROJECT_PROD" ]]; then
  warn "dev and prod must be different projects. Re-run the wizard and pick two IDs."
  exit 1
fi
# Local development talks to dev; config.py reads DIP_GCP_PROJECT.
write_env DIP_GCP_PROJECT "$DIP_GCP_PROJECT_DEV"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Create the projects"
for project in "$DIP_GCP_PROJECT_DEV" "$DIP_GCP_PROJECT_PROD"; do
  if _project_exists "$project"; then
    say "${GREEN}✓${RESET} ${project} already exists, skipping."
    continue
  fi
  warn "Creating ${project} reserves that ID permanently."
  if confirm "Create project ${project}?"; then
    if gcloud projects create "$project" --name="$project" --labels=app=dip; then
      say "${GREEN}✓${RESET} created ${project}"
    else
      warn "couldn't create ${project}. The ID may be taken; re-run and pick another."
      exit 1
    fi
  else
    SKIPPED+=("create project ${project}")
  fi
done
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Link the projects to billing"
for project in "$DIP_GCP_PROJECT_DEV" "$DIP_GCP_PROJECT_PROD"; do
  if ! _project_exists "$project"; then
    warn "${project} doesn't exist, skipping."
    continue
  fi
  linked=$(gcloud billing projects describe "$project" --format='value(billingAccountName)' 2>/dev/null || true)
  if [[ "$linked" == "billingAccounts/${DIP_GCP_BILLING_ACCOUNT}" ]]; then
    say "${GREEN}✓${RESET} ${project} is already linked, skipping."
    continue
  fi
  if confirm "Link ${project} to billing account ${DIP_GCP_BILLING_ACCOUNT}?"; then
    if gcloud billing projects link "$project" --billing-account="$DIP_GCP_BILLING_ACCOUNT" >/dev/null; then
      say "${GREEN}✓${RESET} linked ${project}"
    else
      warn "linking ${project} failed. New billing accounts allow only a few linked"
      warn "projects; request more at the console's billing quota page if needed."
      SKIPPED+=("link ${project} to billing")
    fi
  else
    SKIPPED+=("link ${project} to billing")
  fi
done
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Enable the billing APIs"
say "The budget commands run against a 'quota project'. We use dev for that,"
say "so dev needs the Cloud Billing and Billing Budgets APIs. Enabling them is free."
APIS=(cloudbilling.googleapis.com billingbudgets.googleapis.com)
if confirm "Enable ${APIS[*]} on ${DIP_GCP_PROJECT_DEV}?"; then
  if gcloud services enable "${APIS[@]}" --project="$DIP_GCP_PROJECT_DEV"; then
    say "${GREEN}✓${RESET} APIs enabled"
  else
    warn "enabling the APIs failed. Is ${DIP_GCP_PROJECT_DEV} linked to billing?"
    SKIPPED+=("enable ${APIS[*]} on ${DIP_GCP_PROJECT_DEV}")
  fi
else
  warn "Without these APIs the next stage can't create budgets."
  SKIPPED+=("enable ${APIS[*]} on ${DIP_GCP_PROJECT_DEV}")
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Create budget alerts"
say "One monthly budget per project. Emails go to the billing account's admins"
say "(you) at 50%, 90% and 100% of actual spend, and at 100% of forecast spend."
warn "A budget alert does NOT stop spending. It only emails you."
say ""
ask DIP_GCP_BUDGET_DEV "Monthly budget for dev, in your billing currency [20]:"
DIP_GCP_BUDGET_DEV="${DIP_GCP_BUDGET_DEV:-20}"
ask DIP_GCP_BUDGET_PROD "Monthly budget for prod, in your billing currency [10]:"
DIP_GCP_BUDGET_PROD="${DIP_GCP_BUDGET_PROD:-10}"
write_env DIP_GCP_BUDGET_DEV "$DIP_GCP_BUDGET_DEV"
write_env DIP_GCP_BUDGET_PROD "$DIP_GCP_BUDGET_PROD"

EXISTING_BUDGETS=$(gcloud billing budgets list --billing-account="$DIP_GCP_BILLING_ACCOUNT" \
  --billing-project="$DIP_GCP_PROJECT_DEV" --format='value(displayName)' 2>/dev/null || true)

for pair in "${DIP_GCP_PROJECT_DEV}:${DIP_GCP_BUDGET_DEV}" "${DIP_GCP_PROJECT_PROD}:${DIP_GCP_BUDGET_PROD}"; do
  project="${pair%%:*}"; amount="${pair##*:}"
  name="${project} monthly"
  if grep -Fxq "$name" <<<"$EXISTING_BUDGETS"; then
    say "${GREEN}✓${RESET} budget '${name}' already exists, skipping."
    continue
  fi
  if confirm "Create budget '${name}' for ${amount} per month?"; then
    if gcloud billing budgets create \
        --billing-account="$DIP_GCP_BILLING_ACCOUNT" \
        --billing-project="$DIP_GCP_PROJECT_DEV" \
        --display-name="$name" \
        --budget-amount="$amount" \
        --filter-projects="projects/${project}" \
        --calendar-period=month \
        --threshold-rule=percent=0.5 \
        --threshold-rule=percent=0.9 \
        --threshold-rule=percent=1.0 \
        --threshold-rule=percent=1.0,basis=forecasted-spend >/dev/null; then
      say "${GREEN}✓${RESET} created budget '${name}'"
    else
      warn "couldn't create budget '${name}'. Check you're a Billing Account Administrator."
      SKIPPED+=("budget '${name}'")
    fi
  else
    SKIPPED+=("budget '${name}'")
  fi
done
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Check the budgets in the console"
open_url "https://console.cloud.google.com/billing/${DIP_GCP_BILLING_ACCOUNT}/budgets"
step "Confirm both '<project> monthly' budgets are listed with the right amounts."
step "Open one and check 'Email alerts to billing admins and users' is ticked."
step "Take a screenshot for docs/img/ (Phase 0 deliverable)."
note "Spend shows here with a delay of up to a day; that's normal."
pause "Press Enter when you've checked"

finish
say "Next: tick the GCP items in docs/notes/phase-0.md."
printf '\n'
